<?php

namespace EasyCorp\Bundle\EasyAdminBundle\Tests\Functional\Apps\DefaultApp\Entity\Synthetic;

use Doctrine\ORM\Mapping as ORM;

/**
 * Entity with the same short name as an EasyAdmin field class, used to test
 * the imports of the classes generated by the make:admin:crud command.
 */
#[ORM\Entity]
#[ORM\Table(name: 'maker_form_field')]
class FormField
{
    #[ORM\Id]
    #[ORM\GeneratedValue]
    #[ORM\Column]
    private ?int $id = null;

    public function getId(): ?int
    {
        return $this->id;
    }
}
